// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address newOwner = address(0x5678);
        address originalOwner = address(this);
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        assertTrue(!ok);
        assertEq(c.owner(), originalOwner);
    }
}
